#include <map>
#include <sstream>
#include <string>

struct Game { int gold{ 0 }; int health{ 100 }; };

using Command = void (*)(Game&, int);

class Console
{
public:
    explicit Console(Game& game) : m_game{ game } {}

    void addCommand(const std::string& name, Command fn)
    {
        m_commands[name] = fn;
    }

    bool run(const std::string& line)
    {
        std::istringstream in{ line };
        std::string name;
        int amount{ 0 };
        if (!(in >> name >> amount)) return false;
        const auto found{ m_commands.find(name) };
        if (found == m_commands.end() || found->second == nullptr) return false;
        found->second(m_game, amount);
        return true;
    }

private:
    Game& m_game;
    std::map<std::string, Command> m_commands;
};

unitTests:
void giveGold(Game& g, int n) { g.gold += n; }
void hurt(Game& g, int n) { g.health -= n; }
void setGold(Game& g, int n) { g.gold = n; }
TEST("a command runs")
{
    Game game; Console c{ game };
    c.addCommand("gold", &giveGold);
    CHECK(c.run("gold 50"));
    CHECK_EQ(game.gold, 50);
}
TEST("several commands")
{
    Game game; Console c{ game };
    c.addCommand("gold", &giveGold);
    c.addCommand("hurt", &hurt);
    c.run("hurt 30"); c.run("gold 5"); c.run("gold 5");
    CHECK_EQ(game.health, 70);
    CHECK_EQ(game.gold, 10);
}
TEST("an unknown command does nothing")
{
    Game game; Console c{ game };
    c.addCommand("gold", &giveGold);
    CHECK(!c.run("fly 1"));
    CHECK_EQ(game.gold, 0);
}
TEST("a bad line does nothing")
{
    Game game; Console c{ game };
    c.addCommand("gold", &giveGold);
    CHECK(!c.run("gold"));
    CHECK(!c.run("gold lots"));
    CHECK(!c.run(""));
    CHECK_EQ(game.gold, 0);
}
TEST("registering again replaces")
{
    Game game; Console c{ game };
    c.addCommand("gold", &giveGold);
    c.addCommand("gold", &setGold);
    c.run("gold 7"); c.run("gold 7");
    CHECK_EQ(game.gold, 7);
}
TEST("negative amounts") { Game game; Console c{ game }; c.addCommand("gold", &giveGold); CHECK(c.run("gold -3")); CHECK_EQ(game.gold, -3); }

